function foodPriceOf(d,sea){
  const wave=0.20*Math.sin(d*0.61)+0.10*Math.sin(d*0.173+2.3);
  const seaB=[1,0.95,0.85,1.22][sea]||1;
  const dem=((d%53)<4)?1.35:1;
  return clamp((1+wave)*seaB*dem,0.6,1.8);
}

